/**
 * Removal is a soft delete so the audit log keeps pointing at a real row.
 * `status` is left as it was: it records what the membership was, and
 * `archivedAt` alone says that it ended.
 *
 * The person's work in this org is released in the same transaction: issues
 * they were assigned to become unassigned and projects they led lose their
 * lead. Nothing in the org may keep pointing at a former member.
 */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const row = tx
      .update(members)
      .set(archivePatch())
      .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
      .returning()
      .get();

